CREATE TYPE "Role" AS ENUM ('STUDENT','TEACHER','TEACHER_ASSISTANT','DEPUTY','PRINCIPAL');
CREATE TYPE "Weekday" AS ENUM ('SAT','SUN','MON','TUE','WED');
CREATE TABLE "User" ("id" TEXT NOT NULL,"username" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Classroom" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"grade" TEXT NOT NULL,"academicYear" TEXT NOT NULL,"assistantId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Classroom_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Teacher" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"firstName" TEXT NOT NULL,"lastName" TEXT NOT NULL,"photoUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Teacher_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Student" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"firstName" TEXT NOT NULL,"lastName" TEXT NOT NULL,"nationalId" TEXT NOT NULL,"guardianName" TEXT NOT NULL,"guardianPhone" TEXT NOT NULL,"address" TEXT NOT NULL,"photoUrl" TEXT,"classroomId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Student_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Subject" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"classroomId" TEXT NOT NULL,"teacherId" TEXT NOT NULL,"progress" TEXT,"nextHomework" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Subject_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Schedule" ("id" TEXT NOT NULL,"classroomId" TEXT NOT NULL,"weekday" "Weekday" NOT NULL,"period" INTEGER NOT NULL,"subjectA" TEXT NOT NULL,"subjectB" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Schedule_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Assignment" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"dueDate" TIMESTAMP(3),"teacherId" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"studentId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Assignment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Attendance" ("id" TEXT NOT NULL,"studentId" TEXT NOT NULL,"date" TIMESTAMP(3) NOT NULL,"present" BOOLEAN NOT NULL,"lateMinutes" INTEGER NOT NULL DEFAULT 0,"note" TEXT,CONSTRAINT "Attendance_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Grade" ("id" TEXT NOT NULL,"studentId" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"score" DOUBLE PRECISION NOT NULL,"term" TEXT NOT NULL,CONSTRAINT "Grade_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Lesson" ("id" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"teacherId" TEXT NOT NULL,"progress" TEXT NOT NULL,"nextHomework" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Lesson_pkey" PRIMARY KEY ("id"));
CREATE TABLE "News" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"content" TEXT NOT NULL,"imageUrl" TEXT,"publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"authorId" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "News_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Announcement" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"content" TEXT NOT NULL,"classroomId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"authorId" TEXT NOT NULL,CONSTRAINT "Announcement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_username_key" ON "User"("username"); CREATE UNIQUE INDEX "Classroom_assistantId_key" ON "Classroom"("assistantId"); CREATE UNIQUE INDEX "Teacher_userId_key" ON "Teacher"("userId"); CREATE UNIQUE INDEX "Student_userId_key" ON "Student"("userId"); CREATE UNIQUE INDEX "Student_nationalId_key" ON "Student"("nationalId"); CREATE UNIQUE INDEX "Schedule_classroomId_weekday_period_key" ON "Schedule"("classroomId","weekday","period"); CREATE UNIQUE INDEX "Attendance_studentId_date_key" ON "Attendance"("studentId","date"); CREATE UNIQUE INDEX "Grade_studentId_subjectId_term_key" ON "Grade"("studentId","subjectId","term");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Classroom" ADD CONSTRAINT "Classroom_assistantId_fkey" FOREIGN KEY ("assistantId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Teacher" ADD CONSTRAINT "Teacher_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Student" ADD CONSTRAINT "Student_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Student" ADD CONSTRAINT "Student_classroomId_fkey" FOREIGN KEY ("classroomId") REFERENCES "Classroom"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Subject" ADD CONSTRAINT "Subject_classroomId_fkey" FOREIGN KEY ("classroomId") REFERENCES "Classroom"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Subject" ADD CONSTRAINT "Subject_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "Teacher"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Schedule" ADD CONSTRAINT "Schedule_classroomId_fkey" FOREIGN KEY ("classroomId") REFERENCES "Classroom"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Assignment" ADD CONSTRAINT "Assignment_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "Teacher"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Assignment" ADD CONSTRAINT "Assignment_subjectId_fkey" FOREIGN KEY ("subjectId") REFERENCES "Subject"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Assignment" ADD CONSTRAINT "Assignment_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Attendance" ADD CONSTRAINT "Attendance_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Grade" ADD CONSTRAINT "Grade_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Grade" ADD CONSTRAINT "Grade_subjectId_fkey" FOREIGN KEY ("subjectId") REFERENCES "Subject"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Lesson" ADD CONSTRAINT "Lesson_subjectId_fkey" FOREIGN KEY ("subjectId") REFERENCES "Subject"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Lesson" ADD CONSTRAINT "Lesson_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "Teacher"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "News" ADD CONSTRAINT "News_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Announcement" ADD CONSTRAINT "Announcement_classroomId_fkey" FOREIGN KEY ("classroomId") REFERENCES "Classroom"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Announcement" ADD CONSTRAINT "Announcement_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
-- Note: Session relation is declared by Prisma through User.sessions; User.id must NOT reference Session.
